INSERT INTO public.agent_configuration_catalog(key, definition) VALUES
('imageStorefrontSearchEnabled', '{"key": "imageStorefrontSearchEnabled", "target": "policy", "attribute": "imageStorefrontSearchEnabled", "default": true, "label": "Consultar vitrine na busca por imagem", "description": "Consulta a vitrine oficial quando uma foto pode corresponder a produto ausente do catálogo comercial ativo.", "group": "Busca por imagem", "type": "boolean", "readOnly": false}'::jsonb),
('imageStorefrontPerceptualDistanceMax', '{"key": "imageStorefrontPerceptualDistanceMax", "target": "policy", "attribute": "imageStorefrontPerceptualDistanceMax", "default": 6, "label": "Distância visual máxima da vitrine", "description": "Distância perceptual máxima para confirmar que a foto recebida corresponde à imagem oficial do produto.", "group": "Busca por imagem", "type": "integer", "min": 0, "max": 64, "step": 1, "readOnly": false}'::jsonb),
('imageStorefrontPerceptualMinMargin', '{"key": "imageStorefrontPerceptualMinMargin", "target": "policy", "attribute": "imageStorefrontPerceptualMinMargin", "default": 4, "label": "Margem visual entre variantes", "description": "Diferença mínima entre o melhor resultado visual e a segunda variante para fechar a referência.", "group": "Busca por imagem", "type": "integer", "min": 0, "max": 64, "step": 1, "readOnly": false}'::jsonb),
('message.image_storefront_exact_available', '{"key": "message.image_storefront_exact_available", "target": "message", "type": "textarea", "label": "Imagem identificada na vitrine", "group": "Interpretação de imagens", "description": "Resposta para correspondência visual exata disponível. Preserve {name}, {reference} e {url}.", "maxLength": 1200, "default": "Pela foto, identifiquei o produto: {name}. Referência: {reference}. Link oficial: {url}"}'::jsonb),
('message.image_storefront_exact_unavailable', '{"key": "message.image_storefront_exact_unavailable", "target": "message", "type": "textarea", "label": "Imagem identificada, produto indisponível", "group": "Interpretação de imagens", "description": "Resposta para correspondência visual exata atualmente indisponível. Preserve {name}, {reference} e {url}.", "maxLength": 1200, "default": "Pela foto, identifiquei o produto: {name}. Referência: {reference}. Ele está indisponível no site no momento. Link oficial: {url}"}'::jsonb)
